// =============================================================================
//  The user's Pregnancy FAQ Library (2026-10-13): lib/data/preg_faqs.dart,
//  generated by tools/preg_faqs/docx_to_dart.py.
//
//  The claims, each checked on all 365 rather than one sample:
//    1. Every FAQ the docs hold is here, with its answer and its doctor line.
//    2. A HELD FAQ (clinical sign-off owed) is never shown, suggested, linked
//       or sent to Ask Veda: the hold is real, not a label.
//    3. Each live FAQ is Ask Veda KNOWLEDGE whose body says which stretch of
//       pregnancy it was written for, so the answer can be framed for hers.
//    4. Each opens as a page in the one reader, with no "Reviewed by".
//    5. Ask Veda's suggestions follow her month.
// =============================================================================

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'package:parentveda/ask_veda/pv_veda_corpus.dart';
import 'package:parentveda/ask_veda/pv_veda_links.dart';
import 'package:parentveda/data/preg_faqs.dart';
import 'package:parentveda/screens/reader/pv_reader_screen.dart';
import 'package:parentveda/services/pregnancy_controller.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  group('the library', () {
    test('all 365, Months 1 to 8, ids unique', () {
      expect(kPregFaqsAll, hasLength(365));
      expect([for (final m in kPregFaqMonths) m.month], [1, 2, 3, 4, 5, 6, 7, 8]);
      expect({for (final f in kPregFaqsAll) f.id}, hasLength(365));
    });

    test('every FAQ has its question, its answer and its doctor line', () {
      for (final f in kPregFaqsAll) {
        expect(f.question.trim(), isNotEmpty, reason: f.id);
        expect(f.text(PregFaqSection.direct).trim(), isNotEmpty, reason: '${f.id}: no answer');
        expect(f.of(PregFaqSection.doctor), isNotEmpty, reason: '${f.id}: no doctor line');
      }
    });

    test('the months run on, week after week', () {
      for (var i = 1; i < kPregFaqMonths.length; i++) {
        expect(kPregFaqMonths[i].fromWeek, kPregFaqMonths[i - 1].toWeek + 1,
            reason: 'month ${kPregFaqMonths[i].month}');
      }
    });

    test('no writers\' note reached a reader', () {
      final notes = RegExp(r'Category:|Applicability:|Clinical review:|Verification:|Last verified|Status: Draft');
      for (final f in kPregFaqsAll) {
        for (final p in f.parts) {
          for (final s in [p.heading, ...p.paragraphs, ...p.bullets]) {
            expect(notes.hasMatch(s), isFalse, reason: '${f.id}: "$s"');
          }
        }
      }
    });
  });

  group('the clinical hold', () {
    final held = [for (final f in kPregFaqsAll) if (f.held) f];

    test('39 FAQs wait for sign-off, and none is signed off yet', () {
      expect(held, hasLength(39));
      expect(kPregFaqSignedOff, isEmpty);
      expect(kPregFaqsLive, hasLength(365 - 39));
    });

    test('a held FAQ is never sent to Ask Veda', () {
      final ids = {for (final d in buildPregnancyVedaCorpus()) d['doc_id'] as String};
      for (final f in held) {
        expect(ids, isNot(contains(pvVedaAskId(f.id))), reason: f.id);
      }
    });

    test('a held FAQ never opens, is never suggested and is never a related link', () {
      for (final f in held) {
        expect(pregFaqById(f.id), isNull, reason: f.id);
        expect(pvVedaDocResolves(pvVedaAskId(f.id)), isFalse, reason: f.id);
      }
      final heldIds = {for (final f in held) f.id};
      for (var week = 1; week <= 42; week++) {
        for (final q in pregFaqSuggestions(week)) {
          expect(held.map((f) => f.question), isNot(contains(q)), reason: 'week $week');
        }
      }
      for (final f in kPregFaqsLive) {
        for (final id in pregFaqRead(f).readNext) {
          expect(heldIds, isNot(contains(id.replaceFirst('pvask_', ''))), reason: f.id);
        }
      }
    });
  });

  group('Ask Veda knowledge', () {
    late List<Map<String, dynamic>> asks;
    setUp(() => asks = [
          for (final d in buildPregnancyVedaCorpus())
            if (d['kind'] == 'pvask') d
        ]);

    test('every live FAQ is one document, in the pregnancy domain', () {
      expect(asks, hasLength(kPregFaqsLive.length));
      for (final d in asks) {
        expect(d['domain'], 'pregnancy');
      }
    });

    test('the body leads with the question and says who it was written for', () {
      for (final f in kPregFaqsLive) {
        final body = pvVedaAskBody(f);
        expect(body, startsWith('Q: ${f.question}'), reason: f.id);
        expect(body, contains('Written for:'), reason: f.id);
        expect(body, contains('month ${f.month} of pregnancy'), reason: f.id);
        expect(body, contains('When to speak to your doctor:'), reason: f.id);
      }
    });
  });

  group('the reader', () {
    test('every live FAQ is a page with its answer up top and its doctor line at the foot', () {
      for (final f in kPregFaqsLive) {
        final r = pregFaqRead(f);
        expect(r.reviewed, isFalse, reason: '${f.id}: no clinician has reviewed it');
        expect(r.shortAnswer?.en, f.text(PregFaqSection.direct), reason: f.id);
        expect(r.whenToSeeSomeone.title.en, 'When to speak to your doctor', reason: f.id);
        for (final id in r.readNext) {
          expect(pregFaqReadById(id), isNotNull, reason: '${f.id} -> $id');
        }
      }
    });

    test('a sub-heading the doc wrote keeps its bullets under it', () {
      final f = kPregFaqsLive.firstWhere((f) => f.parts.any((p) => p.heading == 'Can Have'));
      final s = pregFaqRead(f).sections.firstWhere((s) => s.heading?.en == 'Can Have');
      expect(s.bullets, isNotEmpty);
    });

    // Loaded in setUp, outside the widget test's fake clock: `load()` awaited
    // inside testWidgets never completes (as pv_veda_links_test does it).
    late PregnancyController c;
    setUp(() async {
      SharedPreferences.setMockInitialValues({});
      c = PregnancyController(dueDate: DateTime.now().add(const Duration(days: 140)));
      await c.load();
    });

    testWidgets('an FAQ id from an answer card opens the reader on it', (t) async {
      t.view.physicalSize = const Size(1080, 2400);
      t.view.devicePixelRatio = 3.0;
      addTearDown(t.view.reset);
      final f = kPregFaqsLive.first;
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: Builder(
            builder: (ctx) => TextButton(
              onPressed: () => openPvVedaDoc(ctx, pvVedaAskId(f.id), c),
              child: const Text('go'),
            ),
          ),
        ),
      ));
      await t.tap(find.text('go'));
      await t.pump();
      await t.pump(const Duration(milliseconds: 600));
      expect(find.byType(PvReaderScreen), findsOneWidget);
      expect(find.text(f.question), findsWidgets);
      expect(t.takeException(), isNull);
    });
  });

  group('suggestions', () {
    test('follow her month', () {
      expect(pregFaqSuggestions(6), contains('What happens in the second month of pregnancy?'));
      expect(pregFaqSuggestions(6), isNot(contains('What happens in the first month of pregnancy?')));
      expect(pregFaqMonthForWeek(20)?.month, 5);
      expect(pregFaqMonthForWeek(30)?.month, 7);
    });

    test('an unknown week keeps the authored list; past Month 8 reads Month 8', () {
      expect(pregFaqSuggestions(null), isEmpty);
      expect(pregFaqMonthForWeek(38)?.month, 8);
    });

    test('wired: the Ask Veda screen asks for her month', () {
      final src = File('lib/screens/tools/ask_veda_screen.dart').readAsStringSync();
      expect(src, contains('pregFaqSuggestions(p.currentWeek)'));
    });
  });
}
